<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { worldApi } from '../api/world'
import type { ActorSchedule, Relationship } from '../types'
const route = useRoute(); const worldId = Number(route.params.worldId); const actorId = Number(route.params.actorId); const data = ref<{ actor: any; schedules: ActorSchedule[]; relationships: Relationship[] } | null>(null)
onMounted(async () => { const overview = (await worldApi.overview(worldId)).data; data.value = (await worldApi.actor(worldId, actorId, Number(route.query.branchId) || overview.branches[0].id)).data })
</script>
<template><section class="page" v-if="data"><router-link class="back-link" :to="`/worlds/${worldId}/actors`">← 返回角色群像</router-link><div class="profile-hero"><span class="avatar profile-avatar">{{ data.actor.name.slice(0, 1) }}</span><div><p class="eyebrow">ACTOR PROFILE / {{ data.actor.status }}</p><h1>{{ data.actor.name }}</h1><p class="lede">{{ data.actor.role }}</p></div><div class="profile-stats"><strong>{{ data.actor.mood }}<small>MOOD</small></strong><strong>{{ data.actor.energy }}<small>ENERGY</small></strong></div></div><div class="detail-grid"><div class="panel"><div class="panel-heading"><div><p class="eyebrow">SCHEDULE</p><h2>日程</h2></div></div><div class="schedule-row" v-for="item in data.schedules.filter(s => s.actorId === actorId)" :key="item.id"><span>DAY {{ item.dayOfWeek }}</span><strong>{{ item.startTime }}</strong><p>{{ item.activity }}</p></div></div><div class="panel"><div class="panel-heading"><div><p class="eyebrow">RELATIONSHIP GRAPH</p><h2>关系</h2></div></div><div v-if="data.relationships.length" class="relationship-row" v-for="item in data.relationships" :key="item.id"><span>ACTOR #{{ item.fromActorId }} → #{{ item.toActorId }}</span><strong>{{ item.affinity }}</strong><small>affinity</small></div><div v-else class="empty-state">关系还没有被记录。</div></div></div></section><section v-else class="loading-state">正在读取角色记忆…</section></template>
